const chapters=[{"day": 1, "time": 12, "reward": null, "lines": [["VERY", "我刚才想查什么来着？怎么刷起视频了。"], ["心里的声音", "先离这圈通知远点。相机也能让它们安静一会儿。"]], "id": "scroll", "unlock": [3]}, {"day": 1, "time": 24, "reward": "wave", "lines": [["导师消息", "这周整理一下实验结果，先发一版思路给我。"], ["导师消息", "对了，下午组会先讲一下。来得及的话，把那张图也带上。"], ["VERY", "收到。数据、图、结论……先把文件夹找出来。"], ["VERY", "原来“这周”也可以是“今天”。截止日期追上来了，先腾个地方。"]], "id": "task", "unlock": [1]}, {"id": "compare", "day": 2, "time": 5, "unlock": [5], "lines": [["VERY", "刚打开朋友圈，三条成果，四张合影。"], ["心里的声音", "我昨天最大的成果，是修好了那个跑偏的轮子。"], ["VERY", "还挺实用。先别盯别人的进度条了。"]]}, {"day": 2, "time": 12, "reward": null, "lines": [["VERY", "最终版、最终版2、真最终版……我这文件名快写成小说了。"], ["心里的声音", "先把这版写完。那三层改稿壳，一层层敲开。"]], "id": "draft", "unlock": [4]}, {"id": "anxiety", "day": 2, "time": 18, "unlock": [7], "lines": [["VERY", "邮件发了吧？附件带了吧？刚才那个回复是不是太短了？"], ["朋友的消息", "发件箱里都在。你已经检查三遍了。"], ["VERY", "好，先把这几个绕来绕去的问号放下来。"]]}, {"id": "printer", "day": 2, "time": 24, "effect": "printer", "lines": [["打印机", "卡纸。请打开后盖。"], ["VERY", "我只想打一页，它吐出了六张废稿。"], ["同门", "别再点打印了！先把那几张卡住的纸抽出来。"]]}, {"id": "insomnia", "day": 3, "time": 4, "unlock": [6], "lines": [["VERY", "昨晚关灯以后，脑子又开了两小时组会。"], ["心里的声音", "闹钟倒是准时，六点半，一秒都不让。"], ["VERY", "眼皮有点沉，今天把节奏放稳一点。"]]}, {"day": 3, "time": 10, "item": "book", "lines": [["校园通知", "英语考试安排已发布，请同学们留意时间。"], ["VERY", "前几天背的词，终于到你们上班了。"], ["心里的声音", "图书馆那边有本想看的书。顺着箭头过去看看。"]], "id": "exam", "unlock": [2]}, {"id": "illness", "day": 3, "time": 18, "unlock": [8], "lines": [["VERY", "阿嚏——纸巾呢？怎么只剩包装袋了。"], ["朋友的消息", "水杯在你包侧面。别光顾着赶考试。"], ["VERY", "先喝两口。今天连这点小感冒都来凑热闹。"]]}, {"id": "venue", "day": 3, "time": 24, "effect": "rush", "lines": [["校园通知", "考试教室临时调整，请前往隔壁教学楼。"], ["VERY", "准考证上还写着旧教室！"], ["同学", "跟我走，我知道近路。先别跑散。"]]}, {"day": 4, "time": 10, "item": "meal", "lines": [["VERY", "他又出成果了？我昨天还在找一个分号。"], ["朋友的消息", "你那个小车不是跑起来了嘛。晚上吃饭？听你讲讲。"], ["VERY", "走，边吃边吐槽。去食堂拿份热饭。"]], "id": "meal"}, {"id": "recovery", "day": 4, "time": 24, "effect": "recovery", "lines": [["VERY", "软件没响应了……别吧，我刚画好的图。"], ["软件提示", "发现自动恢复文件。"], ["VERY", "打开了！先保存，再备份。刚才那口气终于能喘出来。"]]}, {"day": 5, "time": 10, "item": "camera", "lines": [["VERY", "说好去拍晚霞，一抬头又快天黑了。"], ["心里的声音", "相机就在包里。现在出门，还赶得上最后那点光。"], ["VERY", "走！这张拍完再回来。"]], "id": "sunset"}, {"id": "interview", "day": 5, "time": 24, "item": "headphones", "lines": [["陌生来电", "你好，现在方便聊十分钟吗？"], ["VERY", "方便。等等，我找个安静点的地方。"], ["朋友的消息", "耳机给你留在那边了，别让施工声抢了你的自我介绍。"]]}, {"day": 6, "time": 10, "item": "robot", "lines": [["VERY", "刷新邮箱，刷新邮箱……还是广告。"], ["朋友的消息", "请 AI 助手一起整理作品集吧。晚点再看邮件，我帮你挑挑镜头。"]], "id": "ai"}, {"day": 6, "time": 22, "item": "meal", "lines": [["VERY", "昨晚没睡好，鼻子也堵了。今天这脑子像开了省电模式。"], ["朋友的消息", "先吃点热的，回来睡一会儿。难受就去看看。"], ["同门", "答辩材料忽然提前检查，我先帮你占个位置。热饭拿上，路上别着急。"]], "id": "rest", "effect": "support"}, {"day": 7, "time": 10, "item": "gym", "lines": [["VERY", "待办越划越多，这本子是不是会自己繁殖。"], ["心里的声音", "这一周快走完了。今天把没说出口的话，留给自己听听。"], ["VERY", "行。相机充满电，饭也好好吃。慢慢打。"]], "id": "self"}, {"id": "memory", "day": 7, "time": 24, "effect": "memory", "lines": [["VERY", "旧硬盘居然还能打开。这张是小车第一次跑起来那天。"], ["朋友的消息", "你当时举着相机追了一整圈，笑得可大声了。"], ["VERY", "差点忘了。原来这一周之外，我也攒下了这么多好时候。"]]}];


function introduceTypes(types){for(let type of types){if(introducedTypes.includes(type))continue;introducedTypes.push(type);addEnemy(type);let e=enemies.at(-1);e.x=cam.x+(vw/2-55)*(type%2?1:-1);e.y=cam.y+Math.min(100,vh/4);e.stun=1.5;e.seen=true;ring(e.x,e.y,26,'#efcf8a',1.2)}}
function finishChapter(ch){if(!ch||completedEvents.includes(ch.id))return;completedEvents.push(ch.id);introduceTypes(ch.unlock||[]);if(ch.item)spawnEventItem(ch.item);if(ch.reward==='wave'){if(enemies.some(e=>e.boss&&!e.dead))pendingWave+=8;else spawnTaskWave(8)}if(ch.effect==='printer'){for(let i=0;i<6;i++)addEnemy(4);notice('卡纸风波：六张带改稿壳的废稿加入战场')}if(ch.effect==='rush'){p.eventHaste=6;notice('同学带路：移动暂时加快，赶往新考场')}if(ch.effect==='recovery'){bullets=bullets.filter(b=>!b.enemy);ring(p.x,p.y,220,'#a8ded3',1);notice('恢复成功：眼前的来弹清空了')}if(ch.effect==='support'){p.inv=Math.max(p.inv,6);notice('同门搭把手：短暂保护，去拿热饭吧')}if(ch.effect==='memory'){healPlayer(20);for(let e of enemies)if(!e.boss)e.stun=Math.max(e.stun||0,4);notice('翻到旧照片：补充精力，让催促停一会儿')}hud()}
function showActivity(kind){activity=kind;mode='activity';keys={};joy={x:0,y:0};let details={gym:['健身房 · 把重量慢慢举起来','最后一组，起！好，今天的自己挺有劲。','提升力量与精力，学会释放压力','完成这一组'],book:['图书馆 · 那个卡住的问题','等一下，这页好像能解昨天卡住的问题。折个角，回去试试。','扩大拾取范围，获得成长机会','合上书，记住这个想法'],camera:['河边 · 留住一束光','这束光刚好。蹲低一点，等人走过去——咔嚓。','摄影闪光定格附近困难，留出喘息时间','按下快门'],headphones:['耳机 · 给自己一点安静','把耳机戴上。先不看新消息，听完这首歌。','获得主动降噪保护，按 E 或点耳机按钮开启','戴上耳机'],robot:['AI 助手','这份任务交给你。咱们一起学习，分头处理。','基础攻击随你同步成长；经验不足时待机；空枪也有成本，完成击杀后有收益保障','确认聘请，开始协作']}[kind];modal('<div class="tag">给自己的一小段时间</div><canvas id="activityPic" width="180" height="130" style="position:relative;width:180px;height:130px"></canvas><h2>'+details[0]+'</h2><p class="desc">'+details[1]+'</p><p class="pill">'+details[2]+'</p>'+itemNumberHTML(kind)+'<p><button class="primary" id="activityDone">'+details[3]+'</button></p>');drawLifeItem($('#activityPic').getContext('2d'),90,95,kind,2.3);$('#activityDone').onclick=()=>{if(kind==='headphones'){p.headphones=(p.headphones||0)+1}if(kind==='gym'){p.strength++;p.pulse++;p.max+=20;healPlayer(20);p.damage*=1.35}if(kind==='book'){p.wisdom++;p.magnet+=60;xp+=need}if(kind==='camera'){p.camera++;flashTime=0}if(kind==='robot'){hireAI();}close();mode='play';p.inv=1.5;sound(750,.2,'triangle');notice({headphones:'耳机已戴好：按 E 或点右侧按钮，开启安静时刻',gym:'训练完成：力量会在困难靠近时帮你推开压力',book:'读书的收获：视野更开阔了',camera:'相机已装好：拍照定格附近困难',robot:'AI 助手已加入，跟着你一起完成这一周'}[kind]);hud();if(xp>=need){xp-=need;level++;need=Math.floor(need*1.24+3);levelup()}}}
function showStory(lines,done){storyAction=lines===intro?'intro':chapters.findIndex(c=>c.lines===lines)>=0?'event:'+chapters.find(c=>c.lines===lines).id:lines[0]?.[0]==='另一个自己'?'final':lines[1]?.[0]==='明天'?'day':endless?'endless':'intro';resetJoy();mode='story';keys={};joy={x:0,y:0};storyLines=lines;storyIndex=0;storyDone=done;$('#story').classList.remove('hidden');renderStory()}
function renderStory(){let lesson=starterLessons.findIndex(row=>row[1]===storyLines[storyIndex]?.[1]),demoKind={1:'gym',2:'book',3:'camera',4:'robot',5:'headphones',6:'boost'}[lesson];$('#starterDemo').innerHTML=demoKind?'<iframe title="道具真实机制演示" src="starter-demo.html#'+demoKind+'" tabindex="-1"></iframe>':'';$('#storySkip').style.display=storyAction==='intro'||storyAction==='endless'?'block':'none';let [speaker,line]=storyLines[storyIndex];$('#speaker').textContent=speaker;$('#storyText').textContent=line;$('#storyCount').textContent=(storyIndex+1)+' / '+storyLines.length;let pc=$('#storyPortrait').getContext('2d');pc.clearRect(0,0,100,100);if(speaker==='VERY'||speaker==='心里的声音'||speaker==='另一个自己')drawVeryHero(pc,50,90,{scale:1.5,facing:1});else{pc.fillStyle='#6a8d92';pc.fillRect(20,30,60,45);pc.fillStyle='#172d38';pc.fillRect(27,38,46,23);pc.fillStyle='#f6d794';pc.fillRect(34,44,8,8);pc.fillRect(58,44,8,8);pc.fillStyle='#7caaa5';pc.fillRect(12,48,8,14);pc.fillRect(80,48,8,14);pc.fillRect(46,19,8,11)}}
function advanceStory(){if(mode!=='story')return;if(++storyIndex<storyLines.length)renderStory();else{$('#story').classList.add('hidden');$('#starterDemo').innerHTML='';mode='play';p.inv=1.4;storyDone?.();storyDone=null;if(['intro','endless'].includes(storyAction))beginStarterGather()}}
$('#storyNext').onclick=advanceStory;$('#storySkip').onclick=()=>{if(mode!=='story'||!['intro','endless'].includes(storyAction))return;storyIndex=storyLines.length-1;advanceStory()};
requestAnimationFrame(frame);

function endlessBossHealthFactor(){return endless?.7+.3*Math.min(1,t/180):1}
function endlessScale(){return endless?1+Math.floor(t/30)*.2:1}
function startEndless(){start();endless=true;resetIncidents();checkpoint=null;storyStep=chapters.length;$('#story').classList.add('hidden');storyDone=null;mode='play';close();hud();showStory([['无尽模式','时间越久，敌人的生命和攻击越强。七种Boss随机登场，最多三位同时在场。'],['VERY','每次成长都能免费换一组。撑不住就休息，再试一轮。']].concat(starterLessons),()=>{hud()});}
function carryIntoEndless(){if(mode!=='end'||endless||practice||day!==7||p.hp<=0)return;endless=true;practice=false;checkpoint=null;storyStep=chapters.length;storyDone=null;storyAction=null;storyLines=[];storyIndex=0;activity=null;eventItem=null;pendingWave=0;day=1;dayTime=0;dayBossStarted=false;t=0;kill=0;endlessBosses=0;nextEndlessBoss=20;nextEndlessItem=35;enemies=[];bullets=[];gems=[];fx=[];texts=[];beacons=[];encounterQueue=[];defeatQueue=[];defeatResume='play';spawn=1;fire=0;orbTime=0;pulseTime=0;droneTime=0;flashTime=0;shake=0;freeze=0;damageFlash=0;p.x=p.y=0;p.hp=p.max;p.inv=2;p.vx=p.vy=0;p.cd=p.quietCD=p.quietTime=p.boostTime=p.weakTime=p.weakNext=p.dash=p.areaCD=0;p.eventHaste=0;p.bossRewards=0;p.bossRewardChoice=false;p.bossAfter=null;clearPendingAI();for(let a of p.assistants||[]){a.cd=0}cam={x:0,y:0};keys={};resetJoy();choice=[];rerolls=1;$('#story').classList.add('hidden');hideBossTransition();close();mode='play';resetIncidents();notice('这套装备继续陪你：无尽旅途开始，精力已恢复');hud();if(xp>=need){xp-=need;level++;need=Math.floor(need*1.24+3);levelup()}}
function updateEndless(){day=Math.min(7,1+Math.floor(t/60));if(t>=nextEndlessBoss&&enemies.filter(e=>e.boss&&!e.dead).length<3){let active=enemies.filter(e=>e.boss&&!e.dead).map(e=>e.type),pool=[9,10,6,11,7,8,3].filter(k=>!active.includes(k));addEnemy(pool[Math.floor(gameRandom()*pool.length)],true);nextEndlessBoss=t+Math.max(18,25-Math.floor(t/90));notice('新的挑战加入 · 场上Boss独立行动');}if(t>=nextEndlessItem){spawnEventItem(['meal','book','camera','robot','gym'][Math.floor(gameRandom()*5)]);nextEndlessItem=t+35;}}

function gameRandom(){rngState=(Math.imul(rngState,1664525)+1013904223)>>>0;return rngState/4294967296}
const SAVE_KEY='very-week-save-v1';
function hasLocalSave(){try{return !!localStorage.getItem(SAVE_KEY)}catch{return false}}
function confirmLocal(text,yes,no){modal('<h2>'+text+'</h2><button id="confirmYes">确定</button> <button id="confirmNo">取消</button>');$('#confirmYes').onclick=yes;$('#confirmNo').onclick=no;}
function requestNew(fn){if(hasLocalSave())confirmLocal('开始新一局？原有存档仍保留，保存时再决定是否替换。',fn,home);else fn()}
function snapshotGame(){return {version:2,incidents,storySchema:2,introducedTypes,completedEvents,encounterSeen,encounterQueue,defeatQueue,defeatResume,savedAt:Date.now(),mode:mode==='paused'?resumeMode:mode,enemySerial,rngState,p,enemies,bullets:bullets.map(b=>({...b,hits:[...b.hits].map(e=>enemies.indexOf(e)).filter(i=>i>=0)})),gems,fx,texts,beacons,t,spawn,kill,level,xp,need,bossSpawn,fire,orbTime,pulseTime,droneTime,noticeTime,rerolls,difficulty,storyStep,storyLines,storyIndex,storyAction,activity,eventItem,eventSerial,pendingWave,day,dayTime,dayBossStarted,checkpoint,practice,endless,endlessBosses,nextEndlessBoss,nextEndlessItem,flashTime,cam,choice:choice.map(u=>u.id)}}
function saveLocal(toHome){let state=snapshotGame();let commit=()=>{try{localStorage.setItem(SAVE_KEY,JSON.stringify(state));if(toHome){home();notice('进度已保存在此浏览器')}else{mode=resumeMode;togglePause();notice('已保存到此浏览器')}}catch{modal('<h2>保存失败</h2><p>浏览器可能禁止存储，或空间不足。游戏仍在，先别关闭页面。</p><button id="saveBack">返回游戏</button>');$('#saveBack').onclick=()=>restoreView(resumeMode);}};if(hasLocalSave())confirmLocal('替换已有存档？旧进度将被当前进度覆盖。',commit,()=>{mode=resumeMode;togglePause()});else commit()}
function restoreView(wanted){close();$('#story').classList.add('hidden');mode=wanted;keys={};resetJoy();if(wanted==='encounter')showEncounter();if(wanted==='upgrade')levelup(true,choice);if(wanted==='activity')showActivity(activity);if(wanted==='story'){$('#story').classList.remove('hidden');renderStory()}hud()}
function continueSavedStory(){if(storyAction?.startsWith('event:'))finishChapter(chapters.find(c=>c.id===storyAction.slice(6)));else if(storyAction==='intro'){introduceTypes([0]);saveCheckpoint()}else if(storyAction==='day'){day++;dayTime=0;dayBossStarted=false;spawn=1;planDayIncidents();saveCheckpoint()}else if(storyAction==='final'){end(true);return}hud()}
function loadLocal(){try{let s=JSON.parse(localStorage.getItem(SAVE_KEY));if(![1,2].includes(s?.version)||!s.p||!Number.isFinite(s.p.hp)||!Array.isArray(s.enemies)||!Array.isArray(s.bullets)||!['play','upgrade','story','activity','bossdeath','encounter'].includes(s.mode)||s.enemies.length>600||s.bullets.length>5000)throw Error('invalid');({enemySerial,rngState,p,enemies,gems,fx,texts,beacons,t,spawn,kill,level,xp,need,bossSpawn,fire,orbTime,pulseTime,droneTime,noticeTime,rerolls,difficulty,storyStep,storyLines,storyIndex,storyAction,activity,eventItem,eventSerial,pendingWave,day,dayTime,dayBossStarted,checkpoint,practice,endless,endlessBosses,nextEndlessBoss,nextEndlessItem,flashTime,cam}=s);restoreIncidents(s.incidents);migrateStoryProgress(s);encounterSeen=Array.isArray(s.encounterSeen)?s.encounterSeen:[...new Set(enemies.map(e=>(e.boss?'boss:':'small:')+e.type))];encounterQueue=Array.isArray(s.encounterQueue)?s.encounterQueue:[];defeatQueue=Array.isArray(s.defeatQueue)?s.defeatQueue:[];defeatResume=s.defeatResume||"play";bullets=s.bullets.map(b=>({...b,hits:new Set(b.hits.map(i=>enemies[i]).filter(Boolean))}));choice=s.choice.map(id=>upgrades.find(u=>u.id===id)).filter(Boolean);migrateSave(s.version);storyDone=continueSavedStory;resumeMode=s.mode;restoreView(s.mode);notice('已恢复存档，继续吧')}catch{modal('<h2>没有可用存档</h2><p>存档可能损坏或浏览器不允许读取。原数据未删除。</p><button id="loadBack">返回首页</button>');$('#loadBack').onclick=home;}}

function hireAI(){p.assistants??=[];p.aiLedger??=[];p.aiSerial??=0;p.assistants.push({damage:p.damage,multi:p.multi,burst:p.burst||1,pierce:p.pierce||0,rate:p.rate,cd:0});p.drone=p.assistants.length;}
function syncAI(a,owner){Object.assign(a,{damage:owner.damage,multi:owner.multi,burst:owner.burst||1,pierce:owner.pierce||0,rate:owner.rate});}
function aiFee(a){return .002*Math.pow(Math.max(1,a.damage*a.multi*a.burst*(1+a.pierce*.3)/a.rate),.6)}
function updateAI(dt,target){p.aiLedger??=[];for(let l of p.aiLedger){l.left-=dt;if(!l.closed&&l.left<=0){l.closed=true;}}p.aiLedger=p.aiLedger.filter(l=>!l.closed);for(let i=0;i<(p.assistants||[]).length;i++){let a=p.assistants[i];syncAI(a,p);a.cd-=dt*incidentAttackRate();if(incidentIs('network')||!target||target.dead||!target.seen||!onScreen(target)||a.cd>0||xp<aiFee(a))continue;let fee=aiFee(a);xp=Math.max(0,xp-fee);let ledger={id:++p.aiSerial,paid:fee,left:1.35,closed:false};p.aiLedger.push(ledger);let angle=t*1.4+i*TAU/p.assistants.length,x=p.x+Math.cos(angle)*53,y=p.y+Math.sin(angle)*35-25,aim=Math.atan2(target.y-y,target.x-x);for(let burst=0;burst<a.burst;burst++)for(let j=0;j<a.multi;j++){projectile(x,y,aim+(j-(a.multi-1)/2)*.14,a.damage,false,a.pierce);bullets[bullets.length-1].aiId=ledger.id;}a.cd=a.rate;}}
function attributeAI(b,e){let l=p.aiLedger?.find(k=>k.id===b.aiId&&!k.closed);if(!l)return;e.aiFees=(e.aiFees||0)+l.paid;l.closed=true;}
function settleEnemyAI(e,reward){let fees=e.aiFees||0;e.aiFees=0;return reward>0?Math.max(reward,fees+.25):0;}
function clearPendingAI(){if(!p)return;p.aiLedger=[];}
function updateArea(dt){p.areaCD=(p.areaCD||0)-dt;if(!p.area||p.areaCD>0)return;let damage=6*Math.pow(1.5,p.area-1);ring(cam.x,cam.y,Math.hypot(vw,vh)/2,'#d4c4f2',.7);for(let e of enemies){if(e.dead||Math.abs(e.x-cam.x)>vw/2+e.r||Math.abs(e.y-cam.y)>vh/2+e.r)continue;hit(e,damage,0,0,true,true);}p.areaCD=4;}
function migratePlayer(player){player.boostTime??=Math.max(0,(player.cd||0)-3);player.weakTime??=(player.cd>0&&player.cd<=3?player.cd:0);player.weakNext??=(player.boostTime>0?3:0);player.coffee??=0;player.headphones??=0;player.quietTime??=0;player.quietCD??=0;player.bossRewards??=0;player.bossRewardChoice??=false;player.bossAfter??=null;if(player.area===undefined){player.area=Math.min(5,player.pierce||0);player.pierce=0;}player.areaCD??=0;player.aiLedger??=[];player.aiSerial??=0;if(!player.assistants){player.assistants=[];for(let i=0;i<(player.drone||0);i++)player.assistants.push({damage:player.damage,multi:player.multi,burst:player.burst||1,pierce:0,rate:player.rate,cd:0});}for(let a of player.assistants)syncAI(a,player);player.drone=player.assistants.length;}

function migrateStoryProgress(s){if(s.storySchema===2){introducedTypes=Array.isArray(s.introducedTypes)?s.introducedTypes:[0];completedEvents=Array.isArray(s.completedEvents)?s.completedEvents:[];return}let legacy=['scroll','task','draft','exam','meal','sunset','ai','rest','self'];let current=storyAction?.startsWith('chapter:')?legacy[+storyAction.slice(8)]:null;if(current)storyAction='event:'+current;introducedTypes=[...new Set([0,...enemies.filter(e=>!e.boss).map(e=>e.type),...chapters.filter(c=>c.day<day||c.day===day&&c.time<=dayTime&&c.id!==current).flatMap(c=>c.unlock||[])])];completedEvents=chapters.filter(c=>c.day<day||c.day===day&&c.time<=dayTime&&c.id!==current).map(c=>c.id);if(current){let ch=chapters.find(c=>c.id===current);if(ch){storyLines=ch.lines;storyIndex=Math.min(storyIndex,ch.lines.length-1)}}storyStep=chapters.findIndex(c=>!completedEvents.includes(c.id)&&c.id!==current);if(storyStep<0)storyStep=chapters.length;if(checkpoint){checkpoint.storyStep=chapters.findIndex(c=>c.day>=checkpoint.day);checkpoint.introducedTypes=[0,...chapters.filter(c=>c.day<checkpoint.day).flatMap(c=>c.unlock||[])];checkpoint.completedEvents=chapters.filter(c=>c.day<checkpoint.day).map(c=>c.id)}}
function migrateSave(version){migratePlayer(p);if(checkpoint?.p)migratePlayer(checkpoint.p);enemySerial=Number.isFinite(enemySerial)?enemySerial:0;for(let e of enemies){if(!e.uid)e.uid=++enemySerial;}difficulty=[.72,1,2,4].includes(difficulty)?difficulty:1;storyLines=storyLines.map(line=>line.map(txt=>normalizeAssistantText(txt)));}
home();

function normalizeAssistantText(txt){return txt.replace(/(?:工位\s*[·・]\s*)?(?:做个|自制|制作|组装)\s*(?:机器人|AI\s*助手)/gi,'AI 助手').replace(/(?:制作|组装)\s*(?:机器人|AI\s*助手)/gi,'聘请 AI 助手').replace(/机器人|AI\s*助手(?:零件)?/gi,'AI 助手');}

// Cosmetic transition only: no timers, game modes, save fields or forced reloads.
function hideBossTransition(){const b=$('#bossTransition');if(b)b.className='bossTransition';}
function showBossTransition(e){
 const b=$('#bossTransition');if(!b)return;
 const names={9:'待办清单',10:'消息与拖延',6:'考试周',11:'比较与返工',7:'求职季',8:'毕业',3:'另一个自己'};
 const final=!endless&&e.type===3;
 $('#bossTransitionTag').textContent=endless?'无尽旅途 · 又迈过一关':weekDays[day-1]+' · 今日挑战完成';
 $('#bossTransitionTitle').textContent=final?'和自己，一起向前':names[e.type]+' · 已化解';
 $('#bossTransitionNext').textContent=endless?'喘口气，继续前进':final?'天快亮了。坐一会儿，再出发。':'下一站 · '+weekDays[day]+' · '+dayTitles[day];
 b.className='bossTransition'+(endless?' compact':'');void b.offsetWidth;b.className+=' active';
 sound(final?784:660,.32,'triangle',.045);
}

