function quietActive(){return !!p&&p.quietTime>0}
function healPlayer(amount){p.hp=Math.min(p.max,p.hp+amount*(1+.2*(p.coffee||0)))}
function useHeadphones(){if(p?.starterGather)return;if(mode!=='play'||!p.headphones||p.quietCD>0)return;incidents.active=null;renderIncident();p.quietTime=1+.2*(p.headphones-1);p.quietCD=headphoneCooldown();p.weakTime=0;p.weakNext=0;for(let e of enemies)if(e.trial&&[9,10,6,8,3].includes(e.trial.kind))e.trial.done=true;notice('降噪开启 · 伤害与压力干扰暂时隔绝');sound(360,.18,'sine');hud()}
$('#headphoneSkill').onpointerdown=e=>{e.preventDefault();e.stopPropagation();useHeadphones()};
