function beginStarterGather(){if(p.starterGranted||p.starterGather||practice)return;let items=beacons.filter(b=>!b.used);if(!items.length)return;p.starterGather={elapsed:0,items:items.map(b=>({kind:b.kind,x:b.x,y:b.y}))};resetJoy();keys={};notice('五件装备正在就位…');}
function tickStarterGather(dt){if(document.hidden)return;let g=p.starterGather;if(!g)return;g.elapsed+=dt;let q=clamp(g.elapsed/2,0,1),ease=q*q*(3-2*q);g.items.forEach((it,i)=>{let b=beacons.find(b=>b.kind===it.kind);if(!b)return;let a=i*TAU/5-Math.PI/2;b.x=it.x+(p.x+Math.cos(a)*42-it.x)*ease;b.y=it.y+(p.y+Math.sin(a)*30-it.y)*ease;});if(g.elapsed<2.5)return;if(!p.starterGranted){p.starterGranted=true;for(let it of g.items){let b=beacons.find(b=>b.kind===it.kind);if(b)b.used=true;if(it.kind==='gym'){p.strength++;p.pulse++;p.max+=20;healPlayer(20);p.damage*=1.35}if(it.kind==='book'){p.wisdom++;p.magnet+=60;xp+=need}if(it.kind==='camera'){p.camera++;flashTime=0}if(it.kind==='robot')hireAI();if(it.kind==='headphones')p.headphones++}}p.starterGather=null;p.inv=1.5;notice('五件装备就位，出发！');saveCheckpoint();hud();}

$('#properties').onclick=showProperties;
